def permute_unique(nums):
    nums = sorted(nums)
    out, path, used = [], [], [False] * len(nums)

    def dfs():
        if len(path) == len(nums):
            out.append(path[:])
            return
        for i in range(len(nums)):
            if used[i]:
                continue
            if i > 0 and nums[i] == nums[i - 1] and not used[i - 1]:
                continue                        # equal values go in order
            used[i] = True
            path.append(nums[i])
            dfs()
            path.pop()
            used[i] = False

    dfs()
    return out

def permute_unique(nums):
    counts, out, path = Counter(nums), [], []

    def dfs():
        if len(path) == len(nums):
            out.append(path[:])
            return
        for v in list(counts):
            if counts[v]:
                counts[v] -= 1
                path.append(v)
                dfs()
                path.pop()
                counts[v] += 1

    dfs()
    return out
